import { RUNTIME_FILE, type HostId, type ResolvedConfig } from "@deeplinker/core";
import type { DeferredOutput } from "@deeplinker/deferred/templates";
import { HOST_LABEL } from "../hosts";
import type { DetectedHost } from "../hosts/detect";
import type { GeneratedFile } from "../types";

interface Input {
  config: ResolvedConfig;
  /** Every generated file except this README. */
  files: GeneratedFile[];
  host: DetectedHost;
  hostSteps: string[];
  /** Present when deferred deep linking is on and an endpoint was generated for this host. */
  deferred?: DeferredOutput;
  warnings: string[];
  notes: string[];
}

const origin = (c: ResolvedConfig) => `https://${c.domains[0]}`;

/** Where a generated file goes on the server or in the project, in Markdown. */
export function destination(f: GeneratedFile, c: ResolvedConfig): string {
  if (f.destination) return f.destination;
  if (f.path.startsWith(".well-known/")) return `\`${origin(c)}/${f.path}\``;
  if (f.path === RUNTIME_FILE) return `\`${origin(c)}/${RUNTIME_FILE}\``;
  if (f.path === "snippet.html") return "your pages' `<head>` (paste the contents)";
  if (f.path === "manifest.fragment.json") return "merge into your web app manifest by hand";
  if (f.path === "app-snippets.md") return "read it, then add each snippet to the matching app";
  return `\`${f.path}\``;
}

/** `README-DEPLOY.md`: exactly which files to upload where, for this config and this host. */
export function renderDeployReadme({
  config: c,
  files,
  host,
  hostSteps,
  deferred,
  warnings,
  notes,
}: Input): string {
  const label = HOST_LABEL[host.id as HostId];
  const reason = host.detected
    ? `detected from ${host.evidence.map((e) => `\`${e}\``).join(", ")}`
    : host.id === "static"
      ? "no hosting platform was recognised in the project, so this is written for a plain static host; set `hosting` in your config to change it"
      : "set in your config";

  const lines = [
    `# Deploying deeplinker for ${c.domains.join(", ")}`,
    "",
    `Generated by \`deeplinker build\`. Written for **${label}** (${reason}).`,
    "",
    "## 1. Upload these files",
    "",
    "| File | Goes to | What it does |",
    "| --- | --- | --- |",
    ...files.map((f) => `| \`${f.path}\` | ${destination(f, c)} | ${f.description} |`),
    "",
  ];

  if (c.domains.length > 1) {
    lines.push(
      `Every domain needs the same files at its own root: ${c.domains.map((d) => `\`${d}\``).join(", ")}. Apple, Google and Microsoft each check the domain a link is on.`,
      "",
    );
  }

  lines.push(
    "## 2. The association files must be served like this",
    "",
    "Apple, Google and Microsoft are strict about it, and a mistake fails silently on devices:",
    "",
    "- over HTTPS with a valid certificate, at the root of the domain (`/.well-known/…`)",
    "- directly: **no redirect** (including http → https and example.com → www), no login, nothing that blocks unknown visitors (Apple's CDN fetches the file from its own servers)",
    "- `Content-Type: application/json`",
    "",
    `## 3. ${label}`,
    "",
    ...hostSteps.map((s) => `- ${s}`),
    "",
    "## 4. Add the snippet to your pages",
    "",
    `Paste \`snippet.html\` inside \`<head>\` on every page that should behave as a deep link. It loads \`/${RUNTIME_FILE}\`, which decides what to do for each visitor.`,
    "",
    "## 5. Add the setup to your apps",
    "",
    "Run `npx deeplinker app-snippets` (or read `app-snippets.md`) for the exact entitlement, intent filter and manifest entries each app needs.",
    "",
    "## 6. Check the deployment",
    "",
    "```sh",
    `npx deeplinker verify ${origin(c)}`,
    "```",
    "",
    "It checks each file's status, content type, redirects and contents against your config, then asks Apple's CDN and Google's Digital Asset Links API what they see. Run it after every deploy; add it to CI if you like (it exits non-zero on a failure).",
    "",
  );

  if (deferred) {
    const minutes = Math.round(c.deferred.ttlSeconds / 60);
    lines.push(
      "## 7. Deferred deep linking",
      "",
      `Someone without the app taps a link, goes to the store, installs and opens the app: the app can ask this endpoint where they came from and show the right screen. The endpoint answers \`POST ${c.deferred.basePath}/click\` (the page reports a click that is about to reach a store) and \`POST ${c.deferred.basePath}/match\` (the app asks). Storage: **${deferred.storage}**.`,
      "",
      ...deferred.steps.map((s) => `- ${s}`),
      "",
    );
    if (deferred.dependencies.length) {
      lines.push(`Install: \`npm install ${deferred.dependencies.join(" ")}\``, "");
    }
    if (deferred.env.length) {
      lines.push("It reads:", "", ...deferred.env.map((e) => `- ${e}`), "");
    }
    lines.push(
      `What it keeps, for ${minutes} minute${minutes === 1 ? "" : "s"} per click: the page URL, the first three parts of the visitor's IP address (a /24 for IPv4, a /48 for IPv6, never the full address), the operating system and its major version, the device type and the primary language. It sets no cookie, never stores the user agent, and deletes a click once it has been matched. ${
        c.deferred.clipboard
          ? "The clipboard method is on: the endpoint also accepts a URL the app read from the pasteboard. Putting it there is up to your page (for example, copy the page URL when someone taps your own App Store button), and iOS asks the user before the app can read it."
          : "The clipboard method is off."
      }`,
      "",
      "Each match says how sure it is: `deterministic` (Android, from the Play Install Referrer), `clipboard`, `probabilistic` (iOS, a best guess from the network and device) or `none`. Treat `probabilistic` as a hint, and tell your users that you do this in your privacy policy.",
      "",
    );
  }

  if (warnings.length || notes.length) {
    lines.push(
      "## Notes from the build",
      "",
      ...warnings.map((w) => `- ⚠️ ${w}`),
      ...notes.map((n) => `- ${n}`),
      "",
    );
  }
  return lines.join("\n");
}
